export const IMAGE_BASE64 = CHUNKS.join('')

export const IMAGE_TYPE = 'image/jpeg'
export const IMAGE_WIDTH = 811
export const IMAGE_HEIGHT = 608

let bytes:Uint8Array|null = null

/**
 * Decode the base64 once, then reuse the bytes. `Blob` copies what it
 * is given, so the same array can back any number of files.
 */
export function imageBytes ():Uint8Array {
    if (bytes) return bytes

    const binary = atob(IMAGE_BASE64)
    const arr = new Uint8Array(binary.length)
    for (let i = 0; i < binary.length; i++) {
        arr[i] = binary.charCodeAt(i)
    }
    bytes = arr

    return arr
}

/**
 * A real image `File`. Synchronous, so it drops straight into tests
 * that are not otherwise async.
 */
export function imageFile (name = 'photo.jpg', type = IMAGE_TYPE):File {
    return new File([imageBytes()], name, { type })
}

/**
 * A real image `Blob`. Takes a type because some tests exercise how
 * the component names a blob whose type it does not recognize. The
 * browser sniffs the content, so the bytes still decode whatever
 * type is claimed.
 */
export function imageBlob (type:string = IMAGE_TYPE):Blob {
    return new Blob([imageBytes()], { type })
}

/** The fixture as a data URL, for anything that wants an `img.src`. */
export function imageDataUrl ():string {
    return `data:${IMAGE_TYPE};base64,${IMAGE_BASE64}`
}
